A terrace, free private parking, free WiFi and a 24-hour front desk round out the offering for those staying over. Royal Baeng Private Residence is located at 88 Second Street in Dalmada, on the outskirts of Polokwane, and suits travellers wanting guesthouse accommodation as well as groups looking to hire a function space, meeting room or outdoor venue in one place.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://royal-baeng-private-residence.business.site/', '$[#]', 'https://infohotels.co.za/dalmada-ah/royal-baeng-private-residence-and-gallery-guest-house/'), description_enriched_at = datetime('now') WHERE slug = 'royal-baeng-private-residence-dalmada' AND description = 'Royal Baeng Private Residence is a guesthouse in Dalmada set on a garden property, offering rooms with private bathrooms and air conditioning, a terrace, an on-site restaurant, free private parking, free WiFi and a 24-hour front desk.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
